// Login.js
import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, Link } from "react-router-dom";
import './Login.css'; // Import the CSS file

function Login() {
    const history = useNavigate();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');

    async function submit(e) {
        e.preventDefault();

        try {
            const res = await axios.post("http://localhost:8000/", {
                email,
                password
            });

            if (res.data === "exist") {
                history(`/home?email=${encodeURIComponent(email)}`); // Use query params
            } else if (res.data === "notexist") {
                alert("User has not signed up");
            }
        } catch (error) {
            alert("Wrong details");
            console.error(error);
        }
    }

    return (
        <div className="login-container">  {/* Container for background image */}
            <div className="login-box"> {/* Box for login form */}
                <div className="logo">DigiBank</div> {/* Logo container */}
                <h1>Welcome Back!</h1>  {/* Changed title */}
                <form onSubmit={submit}>
                    <input type="email" onChange={(e) => setEmail(e.target.value)} placeholder="Email" required />
                    <input type="password" onChange={(e) => setPassword(e.target.value)} placeholder="Password" required />
                    <input type="submit" value="Login" />
                </form>
                <div className="signup-link">
                    <p>New to DigiBank? <Link to="/signup">Sign Up</Link></p>
                </div>
            </div>
        </div>
    );
}

export default Login;
